void test_llm_http_status_and_retry_policy(void){uint8_t retries=0U;TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_SUCCESS,net_llm_http_status_classify(200U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_SUCCESS,net_llm_http_status_classify(299U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_AUTH,net_llm_http_status_classify(401U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_AUTH,net_llm_http_status_classify(403U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_RETRYABLE,net_llm_http_status_classify(408U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_RETRYABLE,net_llm_http_status_classify(429U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_RETRYABLE,net_llm_http_status_classify(503U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_PERMANENT,net_llm_http_status_classify(400U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_PERMANENT,net_llm_http_status_classify(302U));TEST_ASSERT_EQUAL(NET_LLM_HTTP_STATUS_PROTOCOL,net_llm_http_status_classify(0U));TEST_ASSERT_EQUAL(1,net_llm_http_retry_consume(503U,2U,&retries));TEST_ASSERT_EQUAL(1U,retries);TEST_ASSERT_EQUAL(1,net_llm_http_retry_consume(429U,2U,&retries));TEST_ASSERT_EQUAL(2U,retries);TEST_ASSERT_EQUAL(0,net_llm_http_retry_consume(500U,2U,&retries));TEST_ASSERT_EQUAL(0,net_llm_http_retry_consume(401U,2U,&retries));TEST_ASSERT_EQUAL(2U,retries);TEST_ASSERT_NOT_EQUAL(0,net_llm_http_retry_consume(503U,1U,0));}

