void test_llm_stream_json_and_sse_fragments(void){net_llm_sse_accumulator_t accumulator,tiny;uint8_t json[128]={0},buffer[96]={0},tiny_buffer[4]={0},text[32]={0};uint16_t text_length=0U;static const uint8_t ollama[]="{\"model\":\"tinyllama\",\"prompt\":\"hi\",\"stream\":true}";static const uint8_t openai[]="{\"model\":\"gpt-4o-mini\",\"messages\":[{\"role\":\"user\",\"content\":\"hi\"}],\"stream\":true}";TEST_ASSERT_EQUAL((int)(sizeof(ollama)-1U),net_llm_build_ollama_generate_stream_json(json,sizeof(json),"tinyllama",(const uint8_t*)"hi",2U));TEST_ASSERT_EQUAL_MEMORY(ollama,json,sizeof(ollama)-1U);TEST_ASSERT_EQUAL((int)(sizeof(openai)-1U),net_llm_build_openai_chat_stream_json(json,sizeof(json),"gpt-4o-mini",(const uint8_t*)"hi",2U));TEST_ASSERT_EQUAL_MEMORY(openai,json,sizeof(openai)-1U);TEST_ASSERT_EQUAL(0,net_llm_sse_accumulator_init(&accumulator,buffer,sizeof(buffer)));TEST_ASSERT_EQUAL(1,net_llm_sse_accumulator_feed(&accumulator,0U,(const uint8_t*)"data: {\"response\":\"bon",22U,text,sizeof(text),&text_length));TEST_ASSERT_EQUAL(0U,text_length);TEST_ASSERT_EQUAL(0,net_llm_sse_accumulator_feed(&accumulator,0U,(const uint8_t*)"jour\"}\n\ndata: [DONE]\n\n",22U,text,sizeof(text),&text_length));TEST_ASSERT_EQUAL(7U,text_length);TEST_ASSERT_EQUAL_MEMORY("bonjour",text,7U);TEST_ASSERT_EQUAL(1U,accumulator.done);TEST_ASSERT_EQUAL(0,net_llm_sse_accumulator_init(&tiny,tiny_buffer,sizeof(tiny_buffer)));TEST_ASSERT_NOT_EQUAL(0,net_llm_sse_accumulator_feed(&tiny,0U,(const uint8_t*)"data:",5U,text,sizeof(text),&text_length));TEST_ASSERT_NOT_EQUAL(0,net_llm_sse_accumulator_init(&accumulator,buffer,0U));TEST_ASSERT_EQUAL(0,net_llm_sse_accumulator_init(&accumulator,buffer,sizeof(buffer)));TEST_ASSERT_NOT_EQUAL(0,net_llm_sse_accumulator_feed(&accumulator,0U,(const uint8_t*)"event: bad\n\n",12U,text,sizeof(text),&text_length));}
void test_llm_sse_chunked_openai_response(void){net_llm_sse_response_t response;uint8_t http_buffer[160]={0},sse_buffer[96]={0},text[32]={0};uint16_t text_length=0U;static const uint8_t input[]="HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n33\r\ndata: {\"choices\":[{\"delta\":{\"content\":\"salut\"}}]}\n\n\r\n0\r\n\r\n";TEST_ASSERT_EQUAL(0,net_llm_sse_response_init(&response,http_buffer,sizeof(http_buffer),sse_buffer,sizeof(sse_buffer)));TEST_ASSERT_EQUAL(0,net_llm_sse_response_feed(&response,1U,input,sizeof(input)-1U,text,sizeof(text),&text_length));TEST_ASSERT_EQUAL(5U,text_length);TEST_ASSERT_EQUAL_MEMORY("salut",text,5U);TEST_ASSERT_EQUAL(1U,response.http.state==8U);}
void test_llm_sse_chunked_ollama_incremental(void){
    net_llm_sse_response_t response;uint8_t http_buffer[160]={0},sse_buffer[96]={0},text[32]={0};uint16_t text_length=0U;
    static const uint8_t first[]="HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n19\r\ndata: {\"response\":\"ok\"}\n\n\r\n";
    static const uint8_t second[]="e\r\ndata: [DONE]\n\n\r\n0\r\n\r\n";
    TEST_ASSERT_EQUAL(0,net_llm_sse_response_init(&response,http_buffer,sizeof(http_buffer),sse_buffer,sizeof(sse_buffer)));
    TEST_ASSERT_EQUAL(1,net_llm_sse_response_feed(&response,0U,first,sizeof(first)-1U,text,sizeof(text),&text_length));
    TEST_ASSERT_EQUAL(2U,text_length);TEST_ASSERT_EQUAL_MEMORY("ok",text,2U);
    TEST_ASSERT_EQUAL(0U,response.sse.done);TEST_ASSERT_NOT_EQUAL(8U,response.http.state);
    TEST_ASSERT_EQUAL(0,net_llm_sse_response_feed(&response,0U,second,sizeof(second)-1U,text,sizeof(text),&text_length));
    TEST_ASSERT_EQUAL(0U,text_length);TEST_ASSERT_EQUAL(1U,response.sse.done);TEST_ASSERT_EQUAL(8U,response.http.state);
}
void test_llm_sse_second_stream_after_reinit(void){
    net_llm_sse_response_t response;uint8_t http_buffer[160]={0},sse_buffer[96]={0},text[32]={0};uint16_t text_length=0U;
    static const uint8_t complete[]="HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n19\r\ndata: {\"response\":\"ok\"}\n\n\r\ne\r\ndata: [DONE]\n\n\r\n0\r\n\r\n";
    static const uint8_t first[]="HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n19\r\ndata: {\"response\":\"go\"}\n\n\r\n";
    static const uint8_t rest[]="e\r\ndata: [DONE]\n\n\r\n0\r\n\r\n";
    TEST_ASSERT_EQUAL(0,net_llm_sse_response_init(&response,http_buffer,sizeof(http_buffer),sse_buffer,sizeof(sse_buffer)));
    TEST_ASSERT_EQUAL(0,net_llm_sse_response_feed(&response,0U,complete,sizeof(complete)-1U,text,sizeof(text),&text_length));
    TEST_ASSERT_EQUAL(2U,text_length);TEST_ASSERT_EQUAL(8U,response.http.state);
    TEST_ASSERT_NOT_EQUAL(0,net_llm_sse_response_feed(&response,0U,first,sizeof(first)-1U,text,sizeof(text),&text_length));
    TEST_ASSERT_EQUAL(0,net_llm_sse_response_init(&response,http_buffer,sizeof(http_buffer),sse_buffer,sizeof(sse_buffer)));
    TEST_ASSERT_EQUAL(1,net_llm_sse_response_feed(&response,0U,first,sizeof(first)-1U,text,sizeof(text),&text_length));
    TEST_ASSERT_EQUAL(2U,text_length);TEST_ASSERT_EQUAL_MEMORY("go",text,2U);
    TEST_ASSERT_EQUAL(0,net_llm_sse_response_feed(&response,0U,rest,sizeof(rest)-1U,text,sizeof(text),&text_length));
    TEST_ASSERT_EQUAL(1U,response.sse.done);TEST_ASSERT_EQUAL(8U,response.http.state);
}

