void test_llm_large_fragmented_unicode_response(void){
    net_http_response_accumulator_t accumulator;net_http_response_view_t response;uint8_t wire[1200]={0},body[1024]={0},output[1024]={0};uint16_t body_length=1015U,first_length=300U,text_length=0U,index=0U;int status;
    static const uint8_t prefix[]={"{\"response\":\""};static const uint8_t suffix[]={'"','}'};static const uint8_t emoji[]={0xf0U,0x9fU,0x98U,0x80U};
    for(index=0U;index<sizeof(prefix)-1U;index++)body[index]=prefix[index];
    for(;index<sizeof(prefix)-1U+996U;index++)body[index]='a';
    for(index=0U;index<sizeof(emoji);index++)body[sizeof(prefix)-1U+996U+index]=emoji[index];
    body[sizeof(prefix)-1U+996U+sizeof(emoji)]=suffix[0];body[sizeof(prefix)-1U+996U+sizeof(emoji)+1U]=suffix[1];
    {static const uint8_t header[]={"HTTP/1.1 200 OK\r\nContent-Length: 1015\r\n\r\n"};for(index=0U;index<sizeof(header)-1U;index++)wire[index]=header[index];for(index=0U;index<body_length;index++)wire[(sizeof(header)-1U)+index]=body[index];}
    TEST_ASSERT_EQUAL(0,net_http_response_accumulator_init(&accumulator,wire,sizeof(wire)));status=net_http_response_accumulator_feed(&accumulator,wire,first_length,&response);TEST_ASSERT_EQUAL(1,status);status=net_http_response_accumulator_feed(&accumulator,wire+first_length,(uint16_t)((sizeof("HTTP/1.1 200 OK\r\nContent-Length: 1015\r\n\r\n")-1U)+body_length-first_length),&response);TEST_ASSERT_EQUAL(0,status);TEST_ASSERT_EQUAL(200,response.status_code);TEST_ASSERT_EQUAL(1000U,response.body_length-13U-2U);TEST_ASSERT_EQUAL(0,net_llm_ollama_response_extract(response.body,response.body_length,output,sizeof(output),&text_length));TEST_ASSERT_EQUAL(1000U,text_length);TEST_ASSERT_EQUAL('a',output[995]);TEST_ASSERT_EQUAL_MEMORY(emoji,output+996U,sizeof(emoji));
}


