void test_llm_http_retry_bounded_backoff(void){uint8_t retries=0U;uint32_t retry_at=0U;TEST_ASSERT_EQUAL(1,net_llm_http_retry_schedule(503U,3U,10U,25U,100U,&retries,&retry_at));TEST_ASSERT_EQUAL(110U,retry_at);TEST_ASSERT_EQUAL(1,net_llm_http_retry_schedule(429U,3U,10U,25U,110U,&retries,&retry_at));TEST_ASSERT_EQUAL(130U,retry_at);TEST_ASSERT_EQUAL(1,net_llm_http_retry_schedule(500U,3U,10U,25U,130U,&retries,&retry_at));TEST_ASSERT_EQUAL(155U,retry_at);TEST_ASSERT_EQUAL(0,net_llm_http_retry_schedule(503U,3U,10U,25U,155U,&retries,&retry_at));retries=0U;retry_at=77U;TEST_ASSERT_NOT_EQUAL(0,net_llm_http_retry_schedule(503U,3U,0U,25U,100U,&retries,&retry_at));TEST_ASSERT_EQUAL(0U,retries);TEST_ASSERT_EQUAL(77U,retry_at);}
void test_llm_bearer_store_lifecycle(void){net_llm_bearer_store_t store={0};uint8_t request[256]={0};static const uint8_t json[]={'{','"','x','"',':','1','}'};static const uint8_t token[]="sk-test-store";static const uint8_t invalid[]={'x','\n'};int length;uint16_t index;TEST_ASSERT_EQUAL(0,net_llm_bearer_store_provision(&store,token,sizeof(token)-1U));TEST_ASSERT_EQUAL(1U,store.provisioned);length=net_http_build_post_json_bearer_store(request,sizeof(request),"api.example.test","/v1/chat",&store,json,sizeof(json));TEST_ASSERT_GREATER_THAN(0,length);TEST_ASSERT_NOT_EQUAL(0,net_llm_bearer_store_provision(&store,invalid,sizeof(invalid)));TEST_ASSERT_NOT_EQUAL(0,net_llm_bearer_store_provision(&store,token,NET_LLM_BEARER_MAX));net_llm_bearer_store_clear(&store);TEST_ASSERT_EQUAL(0U,store.provisioned);TEST_ASSERT_EQUAL(0U,store.length);for(index=0U;index<NET_LLM_BEARER_MAX;index++)TEST_ASSERT_EQUAL(0U,store.token[index]);}
void test_http_tls_post_json_bearer_store_encrypted(void){net_tcp_connection_t client,server;net_tls_aes_gcm_session_t client_session,server_session;net_tcp_view_t view;net_tls_record_view_t record;net_llm_bearer_store_t store={0};static const uint8_t token[]="sk-store-tls";static const uint8_t json[]={ '{','"','x','"',':','1','}' };static const uint8_t expected[]="POST /v1/chat HTTP/1.1\r\nHost: api.example.test\r\nAuthorization: Bearer sk-store-tls\r\nContent-Type: application/json\r\nContent-Length: 7\r\nConnection: close\r\n\r\n{\"x\":1}";uint8_t key_material[40]={0},tcp_segment[320]={0},tls_record[288]={0},request[256]={0},plaintext[256]={0};uint16_t consumed=0U;int length;TEST_ASSERT_EQUAL(0,net_llm_bearer_store_provision(&store,token,sizeof(token)-1U));open_pair(&client,&server,&client_session,&server_session,key_material);length=net_http_tls_build_post_json_bearer_store(&client,&client_session,tcp_segment,sizeof(tcp_segment),tls_record,sizeof(tls_record),request,sizeof(request),"api.example.test","/v1/chat",&store,json,sizeof(json),1U);TEST_ASSERT_GREATER_THAN(0,length);TEST_ASSERT_EQUAL(0,net_tcp_parse(tcp_segment,(uint16_t)length,&view));TEST_ASSERT_EQUAL(0,net_tcp_connection_accept_tls_aes_gcm(&server,&server_session,&view,plaintext,sizeof(plaintext),&record,&consumed));TEST_ASSERT_EQUAL(sizeof(expected)-1U,record.payload_length);TEST_ASSERT_EQUAL_MEMORY(expected,plaintext,sizeof(expected)-1U);net_llm_bearer_store_clear(&store);}

void test_llm_sse_reconnect_scheduler(void){net_llm_sse_response_t response;net_llm_sse_reconnect_t reconnect;uint8_t http_buffer[128]={0},sse_buffer[64]={0};TEST_ASSERT_EQUAL(0,net_llm_sse_response_init(&response,http_buffer,sizeof(http_buffer),sse_buffer,sizeof(sse_buffer)));response.http.length=4U;response.sse.length=3U;TEST_ASSERT_EQUAL(0,net_llm_sse_reconnect_init(&reconnect,2U));TEST_ASSERT_EQUAL(1,net_llm_sse_reconnect_schedule(&reconnect,&response,503U,10U,25U,100U));TEST_ASSERT_EQUAL(1U,reconnect.retries_used);TEST_ASSERT_EQUAL(110U,reconnect.next_tick);TEST_ASSERT_EQUAL(0U,response.http.length);TEST_ASSERT_EQUAL(0U,response.sse.length);TEST_ASSERT_EQUAL(0,net_llm_sse_reconnect_ready(&reconnect,109U));TEST_ASSERT_EQUAL(1,net_llm_sse_reconnect_ready(&reconnect,110U));TEST_ASSERT_EQUAL(1,net_llm_sse_reconnect_schedule(&reconnect,&response,429U,10U,25U,110U));TEST_ASSERT_EQUAL(2U,reconnect.retries_used);TEST_ASSERT_EQUAL(130U,reconnect.next_tick);TEST_ASSERT_EQUAL(0,net_llm_sse_reconnect_schedule(&reconnect,&response,503U,10U,25U,130U));TEST_ASSERT_EQUAL(0,net_llm_sse_reconnect_schedule(&reconnect,&response,200U,10U,25U,130U));}

 void test_llm_sse_retry_hint_applied_to_scheduler(void){net_llm_sse_response_t response;net_llm_sse_reconnect_t reconnect;uint8_t http_buffer[128]={0},sse_buffer[64]={0};TEST_ASSERT_EQUAL(0,net_llm_sse_response_init(&response,http_buffer,sizeof(http_buffer),sse_buffer,sizeof(sse_buffer)));response.sse.retry_valid=1U;response.sse.retry_delay_ms=1500U;TEST_ASSERT_EQUAL(0,net_llm_sse_reconnect_init(&reconnect,3U));TEST_ASSERT_EQUAL(1,net_llm_sse_reconnect_schedule(&reconnect,&response,503U,10U,2500U,100U));TEST_ASSERT_EQUAL(1600U,reconnect.next_tick);TEST_ASSERT_EQUAL(0U,response.sse.retry_valid);TEST_ASSERT_EQUAL(1,net_llm_sse_reconnect_schedule(&reconnect,&response,503U,10U,25U,1600U));TEST_ASSERT_EQUAL(1620U,reconnect.next_tick);response.sse.retry_valid=1U;response.sse.retry_delay_ms=600000U;TEST_ASSERT_EQUAL(1,net_llm_sse_reconnect_schedule(&reconnect,&response,503U,10U,25U,1620U));TEST_ASSERT_EQUAL(1645U,reconnect.next_tick);}

void test_llm_sse_last_event_id_resume(void){
    net_llm_sse_accumulator_t accumulator;net_llm_sse_response_t response;uint8_t sse_buffer[128]={0},http_buffer[128]={0},text[32]={0},request[192]={0};uint16_t text_length=0U;int resume_length;
    static const uint8_t input[]={"id: 42\ndata: {\"response\":\"ok\"}\n\n"};static const uint8_t expected[]={"GET /v1/chat HTTP/1.1\r\nHost: api.example.test\r\nLast-Event-ID: 42\r\nConnection: close\r\n\r\n"};
    TEST_ASSERT_EQUAL(0,net_llm_sse_accumulator_init(&accumulator,sse_buffer,sizeof(sse_buffer)));
    TEST_ASSERT_EQUAL(0,net_llm_sse_accumulator_feed(&accumulator,0U,input,sizeof(input)-1U,text,sizeof(text),&text_length));
    TEST_ASSERT_EQUAL(2U,text_length);TEST_ASSERT_EQUAL_MEMORY("ok",text,2U);
    TEST_ASSERT_EQUAL(1U,accumulator.event_id_valid);TEST_ASSERT_EQUAL(2U,accumulator.event_id_length);TEST_ASSERT_EQUAL_MEMORY("42",accumulator.event_id,2U);
    resume_length=net_http_build_sse_resume_get(request,sizeof(request),"api.example.test","/v1/chat",accumulator.event_id,accumulator.event_id_length);TEST_ASSERT_EQUAL((int)(sizeof(expected)-1U),resume_length);
    TEST_ASSERT_EQUAL_MEMORY(expected,request,sizeof(expected)-1U);
    TEST_ASSERT_EQUAL(0,net_llm_sse_response_init(&response,http_buffer,sizeof(http_buffer),sse_buffer,sizeof(sse_buffer)));response.sse=accumulator;
    TEST_ASSERT_EQUAL(0,net_llm_sse_response_reset(&response));TEST_ASSERT_EQUAL(1U,response.sse.event_id_valid);TEST_ASSERT_EQUAL(2U,response.sse.event_id_length);TEST_ASSERT_EQUAL_MEMORY("42",response.sse.event_id,2U);
    TEST_ASSERT_EQUAL((int)(sizeof(expected)-1U),net_llm_sse_build_resume_get(request,sizeof(request),"api.example.test","/v1/chat",&response));
}

